// src/store/slices/mealsSlice.js
import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";

const API = "http://127.0.0.1:8000/api";

// =============================
// ASYNC THUNKS
// =============================

// Получение списка еды
export const fetchMeals = createAsyncThunk(
  "meals/fetchMeals",
  async (_, { rejectWithValue }) => {
    try {
      const token = localStorage.getItem("access_token");
      const response = await axios.get(`${API}/meals/`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      return response.data;
    } catch (err) {
      return rejectWithValue(err.response.data || "Ошибка при загрузке еды");
    }
  }
);

// Добавление новой еды
export const addMeal = createAsyncThunk(
  "meals/addMeal",
  async (mealData, { rejectWithValue }) => {
    try {
      const token = localStorage.getItem("access_token");
      const response = await axios.post(`${API}/meals/`, mealData, {
        headers: { Authorization: `Bearer ${token}` },
      });
      return response.data;
    } catch (err) {
      return rejectWithValue(err.response.data || "Ошибка при добавлении еды");
    }
  }
);

// =============================
// SLICE
// =============================
const mealsSlice = createSlice({
  name: "meals",
  initialState: {
    items: [],
    loading: false,
    error: null,
  },
  reducers: {
    clearMealsError: (state) => {
      state.error = null;
    },
    removeMeal: (state, action) => {
      state.items = state.items.filter((meal) => meal.id !== action.payload);
    },
  },
  extraReducers: (builder) => {
    // fetchMeals
    builder.addCase(fetchMeals.pending, (state) => {
      state.loading = true;
      state.error = null;
    });
    builder.addCase(fetchMeals.fulfilled, (state, action) => {
      state.loading = false;
      state.items = action.payload;
    });
    builder.addCase(fetchMeals.rejected, (state, action) => {
      state.loading = false;
      state.error = action.payload;
    });

    // addMeal
    builder.addCase(addMeal.pending, (state) => {
      state.loading = true;
      state.error = null;
    });
    builder.addCase(addMeal.fulfilled, (state, action) => {
      state.loading = false;
      state.items.push(action.payload);
    });
    builder.addCase(addMeal.rejected, (state, action) => {
      state.loading = false;
      state.error = action.payload;
    });
  },
});

export const { clearMealsError, removeMeal } = mealsSlice.actions;
export default mealsSlice.reducer;
